-- Questões originais de estudo baseadas em Date, tradução da 8ª edição (2004).
-- Não são questões oficiais do CP-T nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens são rascunhos: revise no painel antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve os registros deste lote.
-- As explicações acompanham o contexto histórico da edição, quando pertinente.
-- Capítulo 20: Herança de tipo — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('2e2d61c4-114f-5f3b-97d0-d794f93b248a', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Banco de Dados', 'Médio', 'Se B é subtipo de A no modelo apresentado, o conjunto de valores de B é:', '["Subconjunto do conjunto de valores de A.","Necessariamente disjunto de A.","Uma variável de relação.","Um arquivo físico separado por definição.","Superconjunto próprio de A."]'::jsonb, 0, 'Todo valor de B também é valor de A.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('97d9a352-242d-5eb9-b7c2-64407843f613', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Banco de Dados', 'Médio', 'Se C é subtipo de B e B é subtipo de A, então:', '["B deixa de existir.","C também é subtipo de A.","A é necessariamente subtipo próprio de C.","C e A são disjuntos obrigatoriamente.","C deve ser um tipo de relação."]'::jsonb, 1, 'A relação de subtipagem é transitiva.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8909900e-40fe-5632-9c9f-d8359c6f5229', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Banco de Dados', 'Médio', 'Um subtipo próprio costuma impor, em relação ao supertipo:', '["Um novo nome para exatamente o mesmo conjunto.","Ausência de operadores.","Obrigação de armazenamento separado.","Restrições adicionais sobre os valores admissíveis.","Menos condições, admitindo todos os valores adicionais."]'::jsonb, 3, 'A especialização restringe o conjunto de valores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('feb96435-1c47-5ea0-9d7c-8c1254e78b13', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Banco de Dados', 'Fácil', 'Em uma hierarquia de tipos, um tipo raiz é aquele que:', '["Não possui supertipo próprio na hierarquia considerada.","É sempre uma relvar básica.","Não possui subtipos.","Possui exatamente um atributo.","Não possui valores."]'::jsonb, 0, 'Raiz e folha descrevem posições distintas na hierarquia.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3626b0e4-4ca7-58bd-a738-0bc8603def16', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Banco de Dados', 'Fácil', 'Um tipo folha, na hierarquia considerada, é aquele que:', '["Não possui subtipo próprio.","Contém todos os demais tipos.","Não pode ter operadores.","Não possui supertipo.","É sempre vazio."]'::jsonb, 0, 'Ser folha não significa estar no topo da hierarquia.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('70f13728-8305-5f77-9163-4ad5da7501f6', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Banco de Dados', 'Médio', 'O polimorfismo por inclusão permite que um operador para A receba:', '["Somente valores sem restrições.","Apenas endereços físicos.","Valores de subtipos de A, respeitado seu contrato.","Apenas relvars sem atributos.","Qualquer valor de tipo incompatível."]'::jsonb, 2, 'A inclusão do conjunto do subtipo no supertipo fundamenta essa possibilidade.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.3, páginas 985–989 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a5b835dc-bc76-5e5a-a41c-2b4faf0f0863', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Banco de Dados', 'Médio', 'Um operador calcula a área de uma figura do tipo ELIPSE. Um valor CÍRCULO pode ser aceito porque:', '["Círculo é um caso particular de elipse no modelo.","Todos os valores geométricos têm a mesma representação.","Operadores ignoram tipos.","A operação transforma qualquer figura em círculo.","Círculos não possuem restrições."]'::jsonb, 0, 'A substituição de valores respeita a inclusão do subtipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.3, páginas 985–989 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3e68eb0e-a1f9-5658-9b67-df30aa2642aa', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Banco de Dados', 'Médio', 'Definir uma implementação especializada de área para retângulos pode trazer:', '["Dispensa de respeitar o tipo do resultado.","Eliminação do supertipo.","Reutilização do contrato com uma implementação mais adequada ao subtipo.","Liberdade para retornar o perímetro no lugar da área.","Mudança obrigatória do significado de área."]'::jsonb, 2, 'Especialização de implementação deve preservar a semântica do operador.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.3, páginas 985–989 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('35406eca-9005-5fd5-9fa7-e71df49d416f', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Banco de Dados', 'Médio', 'Uma variável declarada ELIPSE pode receber um valor CÍRCULO, na hierarquia apresentada?', '["Não, pois valores de subtipos nunca são atribuíveis.","Não, porque variáveis geométricas são constantes.","Sim, apenas se perder o centro.","Sim, porque o valor pertence também ao supertipo.","Sim, mas seu tipo declarado muda obrigatoriamente."]'::jsonb, 3, 'Tipo declarado da variável e tipo mais específico do valor são conceitos distintos.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.4, páginas 990–995 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6a596322-5cf2-5bfc-ac78-9cc2f3f8d994', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Banco de Dados', 'Médio', 'Uma variável declarada CÍRCULO pode receber qualquer valor ELIPSE?', '["Não, porque círculos não são valores.","Não; o valor precisa satisfazer as restrições de círculo.","Sim, se estiver na mesma transação.","Sim, todo supertipo cabe no subtipo.","Sim, se tiver representação binária."]'::jsonb, 1, 'A atribuição ao subtipo exige compatibilidade com seu conjunto de valores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.4, páginas 990–995 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6147f461-a0a3-5ba8-a5f1-620f3d42cee3', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Banco de Dados', 'Médio', 'Receber um valor de subtipo altera necessariamente o tipo declarado de uma variável de supertipo?', '["Sim, se houver operador de leitura.","Sim, mas apenas uma vez.","Não, porque o valor é descartado.","Sim, em toda atribuição.","Não."]'::jsonb, 4, 'A declaração continua delimitando os valores admissíveis da variável.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.4, páginas 990–995 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ab6f4f33-8e8d-53b7-952e-7de75dddcba5', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Banco de Dados', 'Difícil', 'No modelo de especialização por restrição de Date, criar uma elipse com semieixos iguais produz valor cujo tipo mais específico é:', '["POLÍGONO.","CÍRCULO.","Sempre ELIPSE, nunca CÍRCULO.","Uma relvar sem tipo.","RETÂNGULO."]'::jsonb, 1, 'A classificação considera as restrições satisfeitas pelo valor, não apenas o nome do seletor.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.5, páginas 996–999 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('31b1d690-c77b-5059-8cd1-623c2223b9a7', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Banco de Dados', 'Médio', 'Se um valor satisfaz as restrições de um subtipo, sua classificação depende exclusivamente do seletor usado para construí-lo?', '["Sim, porque restrições só valem para variáveis.","Sim, independentemente das propriedades do valor.","Não, no modelo de especialização por restrição apresentado.","Sim, apenas em tipos escalares.","Não, porque nenhum tipo possui seletores."]'::jsonb, 2, 'A discussão separa propriedades do valor e histórico de construção.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.5, páginas 996–999 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('714b655c-1b9d-5644-9bab-39d8cdaec369', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Banco de Dados', 'Médio', 'Comparar valores em uma hierarquia exige considerar:', '["Apenas seus nomes impressos.","O tamanho do nome do usuário.","Compatibilidade de tipos e semântica dos operadores de comparação.","A ordem de criação dos tipos.","Somente seus endereços físicos."]'::jsonb, 2, 'Representações iguais não bastam para estabelecer toda igualdade semântica.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.6, páginas 1000–1004 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('27b2944e-3853-56ab-aca0-e55cf283f766', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Banco de Dados', 'Médio', 'A assinatura de um operador inclui, em linhas gerais:', '["A data do último backup.","A cardinalidade de todas as tabelas.","Somente a localização do código em disco.","A senha do proprietário.","Nome e tipos dos parâmetros pertinentes."]'::jsonb, 4, 'Assinaturas permitem caracterizar e distinguir invocações e versões de operadores.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.7, páginas 1005–1011 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('f3b70a5b-61de-5e22-84b4-2fa509bf8c60', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Banco de Dados', 'Médio', 'Versões especializadas de um mesmo operador devem:', '["Produzir qualquer resultado do mesmo tamanho físico.","Usar obrigatoriamente o mesmo algoritmo.","Trocar o nome do supertipo.","Ignorar restrições do subtipo.","Manter o contrato semântico comum aplicável."]'::jsonb, 4, 'Compatibilidade de tipagem não garante, sozinha, correção do comportamento.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.7, páginas 1005–1011 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d017c8bd-da61-5163-b2fe-bee4153262f9', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Banco de Dados', 'Difícil', 'Alterar apenas um semieixo de uma variável declarada CÍRCULO pode ser inválido porque:', '["Círculos não possuem dimensões.","Operadores de atualização são sempre proibidos no banco.","A variável muda automaticamente para qualquer supertipo.","Pode violar a igualdade dos semieixos exigida pelo subtipo.","Toda elipse exige semieixos distintos."]'::jsonb, 3, 'Restrições da variável precisam ser preservadas em atualizações.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.8, páginas 1012–1017 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('9aeda4dc-670c-5166-939e-2ba67422fcf7', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Banco de Dados', 'Difícil', 'Por que substituição de valores e substituição de variáveis atualizáveis não são equivalentes?', '["Porque leitura sempre altera os dados.","Porque valores possuem endereços permanentes.","Porque subtipos só podem ser usados em texto.","Atualizações precisam respeitar o conjunto de valores permitido pela variável.","Porque variáveis nunca têm tipos."]'::jsonb, 3, 'Uma operação válida para variáveis de supertipo pode produzir valor proibido para uma variável de subtipo.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.8, páginas 1012–1017 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('d91cfd75-877c-5ced-9e29-8f84336c8163', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Banco de Dados', 'Fácil', 'Herança múltipla significa que um tipo pode possuir:', '["Mais de um usuário autorizado.","Mais de um valor, apenas.","Mais de uma variável.","Mais de um índice físico.","Mais de um supertipo imediato."]'::jsonb, 4, 'A quantidade de supertipos imediatos distingue herança simples e múltipla.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.2, páginas 979–984 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false),
('418d18ce-c50d-528d-9ed0-daa5241cb225', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Banco de Dados', 'Médio', 'Polimorfismo por inclusão e sobrecarga de nomes são necessariamente o mesmo mecanismo?', '["Não, porque polimorfismo não admite operadores.","Não; inclusão decorre da hierarquia de subtipos.","Sim, qualquer nome repetido cria subtipos.","Sim, porque tipos são representações físicas.","Sim, desde que o nome tenha parâmetros."]'::jsonb, 1, 'Operadores homônimos não estabelecem, por si só, relação de subtipagem.', 'DATE, C. J. Introdução a Sistemas de Bancos de Dados. Tradução da 8ª edição. Elsevier, 2004. Capítulo 20, seção 20.3, páginas 985–989 do PDF fornecido (numeração do arquivo). Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
